INSERT INTO `prescription_record` VALUES ('2', '869', '2', NULL, '[{"name": "麻黄", "role": "君", "dosage_g": 9.0}, {"name": "石膏", "role": "臣", "dosage_g": 24.0}, {"name": "杏仁", "role": "佐", "dosage_g": 9.0}, {"name": "甘草", "role": "使", "dosage_g": 6.0}, {"name": "鱼腥草", "role": "佐", "dosage_g": 20.0}]', '水煎温服（兽用可拌料）', '连用3-7天', '1', '{"note": "灌服类已按体重系数换算", "safe": true, "score": 0.95, "errors": [], "warnings": ["麻黄: 11.7g 超出人用参考区间 3.0-10.0g（兽用整方给药请对照兽药典）"]}', '{"base_formula": "麻杏石甘汤", "herbs": [{"name": "麻黄", "dosage_g": 9.0, "role": "君"}, {"name": "石膏", "dosage_g": 24.0, "role": "臣"}, {"name": "杏仁", "dosage_g": 9.0, "role": "佐"}, {"name": "甘草", "dosage_g": 6.0, "role": "使"}, {"name": "鱼腥草", "dosage_g": 20.0, "role": "佐"}], "add_notes": ["热毒壅盛、痰黄黏重加鱼腥草20.0g以增强清热解毒之效", "若口渴甚可加芦根15.0g"], "preparation": "水煎温服（兽用可拌料）", "course": "连用3-7天", "contraindications": ["孕猪慎用"], "references": ["伤寒论", "【来源：论治库】证候/疾病：疫热壅肺 → 基础方剂：麻杏石甘汤，组成：甘草6.0g; 麻黄9.0g; 石膏24.0g; 杏仁9.0g，加减：痰黄黏重加:鱼腥草20.0g; 口渴甚加:芦根15.0g，用法：水煎温服（兽用可拌料），疗程：连用3-7天，禁忌：孕猪慎用，出处：伤寒论"]}', '["伤寒论", "【来源：论治库】证候/疾病：疫热壅肺 → 基础方剂：麻杏石甘汤，组成：甘草6.0g; 麻黄9.0g; 石膏24.0g; 杏仁9.0g，加减：痰黄黏重加:鱼腥草20.0g; 口渴甚加:芦根15.0g，用法：水煎温服（兽用可拌料），疗程：连用3-7天，禁忌：孕猪慎用，出处：伤寒论"]', '2026-08-17 16:50:52');
